import math

def build_lines(N, direction_index, lo, hi, include_diam):
    # Returns a list of absolute perpendicular distances from center (radius=1)
    # for all admissible chord lines in the given direction index, restricted to steps in [lo, hi].
    # Only steps with parity matching the direction index contribute lines.
    L = []
    half = N // 2
    p_par = direction_index % 2
    for s in range(lo, hi + 1):
        if s < 1 or s > half:
            continue
        if s == half:
            # diameter contributes a single line at distance 0
            if include_diam == 1 and (s % 2) == p_par:
                L.append(0.0)
            continue
        if (s % 2) == p_par:
            d = abs(math.cos(math.pi * s / N))
            # two parallel lines at +d and -d (stored as absolute distances)
            L.append(d)
            L.append(d)
    return L

def count_rectangles(N, a1, b1, a2, b2, include_diameter):
    total = 0
    eps = 1e-12
    half = N // 2
    for p in range(half):
        q = p + half  # perpendicular direction
        Lh = build_lines(N, p, a1, b1, include_diameter)
        Lv = build_lines(N, q, a2, b2, include_diameter)
        if len(Lh) < 2 or len(Lv) < 2:
            continue
        # Precompute maxima of unordered pairs in each direction
        max_h = []
        for i in range(len(Lh)):
            for j in range(i + 1, len(Lh)):
                max_h.append(max(Lh[i], Lh[j]))
        max_v = []
        for i in range(len(Lv)):
            for j in range(i + 1, len(Lv)):
                max_v.append(max(Lv[i], Lv[j]))
        # Validity: for rectangle corners (±x, ±y) to lie on both chords segments in the unit circle,
        # we need max(x)^2 + max(y)^2 <= 1.
        for mh in max_h:
            thresh = 1.0 - mh * mh + eps
            for mv in max_v:
                if mv * mv <= thresh:
                    total += 1
    return total

